# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">THEME 2: CLASSROOM LIFE, STUDY STRATEGIES &amp; DIGITAL TOOLS</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SCHOOL LIFE &amp; EXTRACURRICULAR CLUBS</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• boarding school (yatılı okul) | graduate (mezun olmak)</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• extracurricular activity (ders dışı sosyal etkinlik)</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• coding / chess / literature / volunteering club</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• laboratory work (laboratuvar çalışması) | presentation</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• ambitious (hırslı/azimli) | perfectionist (mükemmeliyetçi)</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">STUDY STRATEGIES &amp; DIGITAL LEARNING</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• mind mapping (zihin haritası) | brainstorming (beyin fırtınası)</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• note-taking (not alma) | self-assessment (öz değerlendirme)</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• time management (zaman yönetimi) | repetition (tekrar)</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• analyse (analiz etmek) | summarise (özetlemek) | visualise</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• artificial intelligence (AI) | log in / log out | upload</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Visual learners prefer \'mind mapping and charts\', while auditory learners prefer \'discussions and podcasts\'.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">FUTURE FORMS: \'BE GOING TO\' VS. \'WILL\' IN ACADEMIC CONTEXTS</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">\'BE GOING TO\' (PLANS &amp; EVIDENCE)</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Form: am / is / are + going to + Verb 1</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• 1. Prior Plans &amp; Intentions (Önceden planlanmış hedefler):</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• • \'I am going to join the coding club this semester.\'</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• 2. Predictions with Present Evidence (Kanıtlı tahmin):</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• • \'Look at the schedule! The presentation is going to start.\'</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">\'WILL\' (INSTANT DECISIONS &amp; OPINIONS)</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• Form: will / won\'t (will not) + Verb 1</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• 1. Spontaneous Decisions, Offers &amp; Promises (Ani karar/söz):</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• • \'The board is dirty; I will clean it right now.\'</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• 2. Personal Predictions (think, believe, hope, probably):</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• • \'I believe digital platforms will replace printed notes.\'</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Anahtar İpucu: Önceden yapılmış çalışma planı -&gt; \'be going to\' | Konuşma anında karar veya \'I think/probably\' -&gt; \'will\'.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MODALS FOR STUDY ADVICE, OBLIGATION &amp; PROHIBITION</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">ADVICE &amp; NECESSITY (TAVSİYE VE ZORUNLULUK)</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• should / ought to + V₁ : Tavsiye (You should take notes).</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• had better + V₁ : Güçlü tavsiye (You\'d better manage your time).</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• must + V₁ : İçsel zorunluluk / kural (I must revise today).</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• have to / has to + V₁ : Dışsal zorunluluk (We have to wear IDs).</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• need to + V₁ : Gereklilik (You need to do self-assessment).</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">PROHIBITION VS. LACK OF NECESSITY</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• mustn\'t + V₁ : YASAKLAMA (Yapmamalısın / Yasak!).</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• • \'Students mustn\'t cheat during the quiz.\'</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• don\'t / doesn\'t have to + V₁ : GEREK YOK (Zorunlu değil).</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• • \'You don\'t have to memorise everything; summarise it.\'</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Dikkat: Olumlu hâlde must ≈ have to; olumsuzda anlam farklıdır!</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Akademik başarı için zaman yönetimi (time management) ve düzenli öz değerlendirme (self-assessment) şarttır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
